// xdp_lb.c - 简单的 XDP 负载均衡器
#include "vmlinux.h"
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 256);
    __type(key, __u32);     // 目标 IP
    __type(value, __u32);   // 后端 IP
} backends SEC(".maps");

SEC("xdp")
int xdp_load_balancer(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return XDP_PASS;

    // 只处理 TCP
    if (iph->protocol != IPPROTO_TCP)
        return XDP_PASS;

    // 查找后端
    __u32 vip = iph->daddr;
    __u32 *backend = bpf_map_lookup_elem(&backends, &vip);
    if (!backend)
        return XDP_PASS;

    // 替换目标 IP
    iph->daddr = *backend;

    // 重新计算校验和
    iph->check = 0;
    iph->check = bpf_csum_diff(0, 0, (__be32 *)iph, sizeof(*iph), 0);

    // 修改 MAC 地址（简化）
    // ...

    return XDP_TX;
}

// tc_mark.c - 使用 TC eBPF 标记流量
#include "vmlinux.h"
#include <bpf/bpf_helpers.h>

SEC("tc")
int tc_mark_priority(struct __sk_buff *skb) {
    void *data = (void *)(long)skb->data;
    void *data_end = (void *)(long)skb->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return TC_ACT_OK;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return TC_ACT_OK;

    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end)
        return TC_ACT_OK;

    // 标记高优先级流量
    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (void *)(iph + 1);
        if ((void *)(tcp + 1) > data_end)
            return TC_ACT_OK;

        // HTTPS 流量标记为高优先级
        if (tcp->dest == bpf_htons(443)) {
            skb->priority = 100;
        }
    }

    return TC_ACT_OK;
}
